-- End-to-end coaching marketplace: services, orders, bookings, products, and private messaging.
create type public.marketplace_service_type as enum ('ASYNC_REVIEW','LIVE_SESSION','DIGITAL_PRODUCT','CUSTOM_SERVICE');
create type public.marketplace_order_status as enum ('DRAFT','PENDING','ACCEPTED','IN_PROGRESS','DELIVERED','REVISION_REQUESTED','COMPLETED','CANCELLED','DECLINED');
create type public.booking_status as enum ('REQUESTED','CONFIRMED','COMPLETED','CANCELLED','NO_SHOW');
create type public.message_kind as enum ('TEXT','IMAGE','FILE','VIDEO','SYSTEM');

alter table public.professional_profiles add column if not exists languages text[] not null default '{}';
alter table public.professional_profiles add column if not exists location text;
alter table public.professional_profiles add column if not exists response_time_hours integer check(response_time_hours >= 0);
alter table public.professional_services add column if not exists service_type public.marketplace_service_type not null default 'ASYNC_REVIEW';
alter table public.professional_services add column if not exists category text not null default 'Coaching';
alter table public.professional_services add column if not exists subcategory text;
alter table public.professional_services add column if not exists tags text[] not null default '{}';
alter table public.professional_services add column if not exists gallery_urls text[] not null default '{}';
alter table public.professional_services add column if not exists requirements text[] not null default '{}';
alter table public.professional_services add column if not exists faq jsonb not null default '[]'::jsonb;

create table public.service_packages (id uuid primary key default gen_random_uuid(),service_id uuid not null references public.professional_services(id) on delete cascade,name text not null check(name in ('BASIC','STANDARD','PREMIUM')),description text not null default '',price_cents integer not null default 0 check(price_cents >= 0),delivery_days integer not null default 3 check(delivery_days between 1 and 365),revisions integer not null default 0 check(revisions >= 0),features text[] not null default '{}',max_video_seconds integer check(max_video_seconds >= 0),max_file_bytes bigint check(max_file_bytes >= 0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(service_id,name));
create table public.service_extras (id uuid primary key default gen_random_uuid(),service_id uuid not null references public.professional_services(id) on delete cascade,title text not null,description text not null default '',price_cents integer not null default 0 check(price_cents >= 0),delivery_days_delta integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(),professional_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text not null default '',category text not null default 'Digital resource',price_cents integer not null default 0 check(price_cents >= 0),image_urls text[] not null default '{}',download_url text,stock integer check(stock >= 0),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id) on delete restrict,professional_id uuid not null references public.profiles(id) on delete restrict,service_id uuid references public.professional_services(id) on delete set null,package_id uuid references public.service_packages(id) on delete set null,product_id uuid references public.products(id) on delete set null,status public.marketplace_order_status not null default 'DRAFT',requirements text,subtotal_cents integer not null default 0 check(subtotal_cents >= 0),extras_cents integer not null default 0 check(extras_cents >= 0),total_cents integer not null default 0 check(total_cents >= 0),delivery_due_at timestamptz,delivered_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(buyer_id <> professional_id),check(service_id is not null or product_id is not null));
create table public.order_extras (order_id uuid not null references public.orders(id) on delete cascade,extra_id uuid references public.service_extras(id) on delete set null,title text not null,price_cents integer not null default 0,primary key(order_id,extra_id));
create table public.order_attachments (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,uploaded_by uuid not null references public.profiles(id) on delete cascade,name text not null,url text not null,mime_type text,file_size bigint,created_at timestamptz not null default now());
create table public.order_deliveries (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,professional_id uuid not null references public.profiles(id) on delete cascade,message text,created_at timestamptz not null default now());
create table public.order_revisions (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,buyer_id uuid not null references public.profiles(id) on delete cascade,message text not null,created_at timestamptz not null default now());
create table public.availability_rules (id uuid primary key default gen_random_uuid(),professional_id uuid not null references public.profiles(id) on delete cascade,weekday smallint not null check(weekday between 0 and 6),start_time time not null,end_time time not null,timezone text not null default 'UTC',session_minutes integer not null default 60 check(session_minutes between 15 and 480),buffer_minutes integer not null default 0 check(buffer_minutes >= 0),max_bookings_per_day integer not null default 1 check(max_bookings_per_day > 0),created_at timestamptz not null default now(),check(end_time > start_time));
create table public.bookings (id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id) on delete restrict,professional_id uuid not null references public.profiles(id) on delete restrict,service_id uuid not null references public.professional_services(id) on delete restrict,status public.booking_status not null default 'REQUESTED',starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at > starts_at));
create table public.conversations (id uuid primary key default gen_random_uuid(),order_id uuid unique references public.orders(id) on delete set null,booking_id uuid unique references public.bookings(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.conversation_participants (conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,read_at timestamptz,archived_at timestamptz,muted_at timestamptz,primary key(conversation_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid references public.profiles(id) on delete set null,kind public.message_kind not null default 'TEXT',body text,created_at timestamptz not null default now(),check(kind='SYSTEM' or sender_id is not null));
create table public.message_attachments (id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,name text not null,url text not null,mime_type text,file_size bigint,created_at timestamptz not null default now());
create table public.marketplace_reviews (id uuid primary key default gen_random_uuid(),order_id uuid unique not null references public.orders(id) on delete cascade,buyer_id uuid not null references public.profiles(id) on delete cascade,professional_id uuid not null references public.profiles(id) on delete cascade,rating smallint not null check(rating between 1 and 5),body text,created_at timestamptz not null default now());
create table public.saved_professionals (user_id uuid not null references public.profiles(id) on delete cascade,professional_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,professional_id),check(user_id <> professional_id));

create index orders_buyer_idx on public.orders(buyer_id,status,created_at desc); create index orders_professional_idx_v2 on public.orders(professional_id,status,created_at desc); create index messages_conversation_idx on public.messages(conversation_id,created_at); create index bookings_professional_idx on public.bookings(professional_id,starts_at); create index products_professional_idx on public.products(professional_id,is_active);
create trigger packages_updated before update on public.service_packages for each row execute procedure public.set_updated_at(); create trigger products_updated before update on public.products for each row execute procedure public.set_updated_at(); create trigger marketplace_orders_updated before update on public.orders for each row execute procedure public.set_updated_at(); create trigger bookings_updated before update on public.bookings for each row execute procedure public.set_updated_at(); create trigger conversations_updated before update on public.conversations for each row execute procedure public.set_updated_at();
create or replace function public.is_conversation_member(conversation_uuid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_participants where conversation_id=conversation_uuid and user_id=auth.uid()) $$;
create or replace function public.create_order_conversation() returns trigger language plpgsql security definer set search_path=public as $$ declare convo uuid; begin insert into public.conversations(order_id) values(new.id) returning id into convo; insert into public.conversation_participants(conversation_id,user_id) values(convo,new.buyer_id),(convo,new.professional_id); insert into public.messages(conversation_id,kind,body) values(convo,'SYSTEM','Order created'); return new; end; $$;
create trigger order_conversation after insert on public.orders for each row execute procedure public.create_order_conversation();
alter table public.service_packages enable row level security; alter table public.service_extras enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_extras enable row level security; alter table public.order_attachments enable row level security; alter table public.order_deliveries enable row level security; alter table public.order_revisions enable row level security; alter table public.availability_rules enable row level security; alter table public.bookings enable row level security; alter table public.conversations enable row level security; alter table public.conversation_participants enable row level security; alter table public.messages enable row level security; alter table public.message_attachments enable row level security; alter table public.marketplace_reviews enable row level security; alter table public.saved_professionals enable row level security;
create policy packages_public_read on public.service_packages for select using(exists(select 1 from public.professional_services s where s.id=service_id and (s.is_published or s.professional_id=auth.uid() or public.is_admin()))); create policy packages_manage on public.service_packages for all using(exists(select 1 from public.professional_services s where s.id=service_id and (s.professional_id=auth.uid() or public.is_admin())) ) with check(exists(select 1 from public.professional_services s where s.id=service_id and (s.professional_id=auth.uid() or public.is_admin())));
create policy extras_public_read on public.service_extras for select using(exists(select 1 from public.professional_services s where s.id=service_id and (s.is_published or s.professional_id=auth.uid() or public.is_admin()))); create policy extras_manage on public.service_extras for all using(exists(select 1 from public.professional_services s where s.id=service_id and (s.professional_id=auth.uid() or public.is_admin()))) with check(exists(select 1 from public.professional_services s where s.id=service_id and (s.professional_id=auth.uid() or public.is_admin())));
create policy products_public_read on public.products for select using(is_active or professional_id=auth.uid() or public.is_admin()); create policy products_manage on public.products for all using(professional_id=auth.uid() or public.is_admin()) with check(professional_id=auth.uid() or public.is_admin());
create policy orders_read_v2 on public.orders for select using(buyer_id=auth.uid() or professional_id=auth.uid() or public.is_admin()); create policy orders_create_v2 on public.orders for insert with check(buyer_id=auth.uid() and buyer_id <> professional_id and exists(select 1 from public.professional_services s where s.id=service_id and s.professional_id=professional_id and s.is_published)); create policy orders_update_v2 on public.orders for update using(buyer_id=auth.uid() or professional_id=auth.uid() or public.is_admin()) with check(buyer_id=auth.uid() or professional_id=auth.uid() or public.is_admin());
create policy order_children_read on public.order_extras for select using(exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or o.professional_id=auth.uid() or public.is_admin()))); create policy order_attachments_secure on public.order_attachments for all using(exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or o.professional_id=auth.uid() or public.is_admin()))) with check(uploaded_by=auth.uid() and exists(select 1 from public.orders o where o.id=order_id and (o.buyer_id=auth.uid() or o.professional_id=auth.uid() or public.is_admin())));
create policy availability_public_read on public.availability_rules for select using(true); create policy availability_manage on public.availability_rules for all using(professional_id=auth.uid() or public.is_admin()) with check(professional_id=auth.uid() or public.is_admin()); create policy bookings_secure on public.bookings for all using(buyer_id=auth.uid() or professional_id=auth.uid() or public.is_admin()) with check(buyer_id=auth.uid() or professional_id=auth.uid() or public.is_admin());
create policy conversations_secure on public.conversations for select using(public.is_conversation_member(id) or public.is_admin()); create policy participants_secure on public.conversation_participants for select using(user_id=auth.uid() or public.is_admin()); create policy participants_update on public.conversation_participants for update using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy messages_secure on public.messages for select using(public.is_conversation_member(conversation_id) or public.is_admin()); create policy messages_send on public.messages for insert with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id)); create policy attachments_secure on public.message_attachments for select using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id)));
create policy reviews_public_read on public.marketplace_reviews for select using(true); create policy reviews_verified_create on public.marketplace_reviews for insert with check(buyer_id=auth.uid() and exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=auth.uid() and o.professional_id=professional_id and o.status='COMPLETED')); create policy saved_manage on public.saved_professionals for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
alter table public.messages replica identity full; alter publication supabase_realtime add table public.messages;
create policy attachments_send on public.message_attachments for insert with check(exists(select 1 from public.messages m where m.id=message_id and m.sender_id=auth.uid() and public.is_conversation_member(m.conversation_id)));
